// Generated by vcv/tools/make-plugin.js. One generic module; each bank in bank.hpp is its own model.
#include "plugin.hpp"
#include "bank.hpp"

// 0 V is the item's From setting in the app, 10 V its To. Values go out as MIDI CC when they change.
// Every module remembers the MIDI device last chosen on any Curiosities module, so a new one is ready to go.
static json_t* lastMidiJ = NULL;

static const NVGcolor LEVEL_COLORS[4] = {
  nvgRGB(0xc4, 0x47, 0x2f), // curiosity
  nvgRGB(0xc9, 0x8a, 0x14), // suite
  nvgRGB(0x2f, 0x7f, 0x78), // proximity
  nvgRGB(0x5d, 0x4f, 0xa8), // proximity suite
};

// ---------- OSC over UDP to the desktop app's bridge (127.0.0.1:7000), the second way out besides MIDI ----------
// Address /curio/set/<level>/<id> with one float 0..1, as in the desktop bridge (apps/curiosities/desktop/README.md).
#if defined(ARCH_WIN)
  #include <winsock2.h>
  #include <ws2tcpip.h>
  typedef SOCKET curio_socket;
  #define CURIO_BAD_SOCKET INVALID_SOCKET
#else
  #include <sys/socket.h>
  #include <netinet/in.h>
  #include <arpa/inet.h>
  #include <unistd.h>
  typedef int curio_socket;
  #define CURIO_BAD_SOCKET (-1)
#endif
#include <cstring>

struct CurioOsc {
  curio_socket sock = CURIO_BAD_SOCKET;
  sockaddr_in addr;

  bool open() {
    if (sock != CURIO_BAD_SOCKET)
      return true;
#if defined(ARCH_WIN)
    WSADATA wsa;
    WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == CURIO_BAD_SOCKET)
      return false;
    std::memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(7000);
    addr.sin_addr.s_addr = htonl(0x7f000001); // 127.0.0.1
    return true;
  }

  static void pad(std::string& b) {
    do b.push_back('\0'); while (b.size() % 4);
  }

  // One OSC message with one big-endian int32 (",i").
  void sendInt(const std::string& address, int32_t v) {
    if (!open())
      return;
    std::string b = address;
    pad(b);
    b += ",i";
    pad(b);
    uint32_t u = htonl((uint32_t) v);
    b.append((const char*) &u, 4);
    sendto(sock, b.data(), (int) b.size(), 0, (const sockaddr*) &addr, sizeof(addr));
  }

  // One OSC message: the address, the type tag ",f", one big-endian float.
  void sendFloat(const std::string& address, float v) {
    if (!open())
      return;
    std::string b = address;
    pad(b);
    b += ",f";
    pad(b);
    uint32_t u;
    std::memcpy(&u, &v, 4);
    u = htonl(u);
    b.append((const char*) &u, 4);
    sendto(sock, b.data(), (int) b.size(), 0, (const sockaddr*) &addr, sizeof(addr));
  }
};
static CurioOsc curioOsc;

// "c:music" -> "/curio/set/c/music" (or "/curio/trigger/c/music")
static std::string oscAddress(const char* key, const char* verb = "set") {
  std::string k = key;
  size_t colon = k.find(':');
  if (colon == std::string::npos)
    return "";
  return std::string("/curio/") + verb + "/" + k.substr(0, colon) + "/" + k.substr(colon + 1);
}

struct CurioModule : Module {
  const CurioBank* bank;
  midi::Output midiOutput;
  int lastValues[16];
  float lastOsc[16];
  bool useOsc = false; // send OSC to the desktop app instead of MIDI
  bool gateOn[16] = {};
  dsp::ClockDivider sendDivider;
  dsp::ClockDivider rememberDivider;

  CurioModule(const CurioBank* b) : bank(b) {
    config(0, 32, 0, 0);
    for (int i = 0; i < 16; i++) {
      if (i < bank->count) {
        configInput(i, bank->jacks[i].label);
        configInput(16 + i, std::string(bank->jacks[i].label) + ": on/off gate (OSC)");
      }
      else {
        configInput(i, "Unused");
        configInput(16 + i, "Unused");
      }
    }
    sendDivider.setDivision(64);
    rememberDivider.setDivision(48000);
    onReset();
  }

  void onReset() override {
    for (int i = 0; i < 16; i++) {
      lastValues[i] = -1;
      lastOsc[i] = -1.f;
    }
    midiOutput.reset();
    if (lastMidiJ)
      midiOutput.fromJson(lastMidiJ);
    midiOutput.setChannel(bank->channel - 1);
  }

  void process(const ProcessArgs& args) override {
    if (rememberDivider.process()) {
      // Remember this module's device for the next one added.
      if (midiOutput.getDeviceId() >= 0) {
        if (lastMidiJ)
          json_decref(lastMidiJ);
        lastMidiJ = midiOutput.toJson();
      }
    }
    if (!sendDivider.process())
      return;
    if (useOsc && bank->jacks[0].key[0]) {
      // Gates switch the item on and off: /curio/trigger/<level>/<id> 1 on the rise, 0 on the fall.
      for (int i = 0; i < bank->count; i++) {
        if (!inputs[16 + i].isConnected())
          continue;
        bool high = inputs[16 + i].getVoltage() >= 1.f;
        if (high == gateOn[i])
          continue;
        gateOn[i] = high;
        curioOsc.sendInt(oscAddress(bank->jacks[i].key, "trigger"), high ? 1 : 0);
      }
      // OSC keeps fine steps: anything that moved by more than about 0.1% goes out.
      for (int i = 0; i < bank->count; i++) {
        if (!inputs[i].isConnected())
          continue;
        float m = clamp(inputs[i].getVoltage() / 10.f, 0.f, 1.f);
        if (std::fabs(m - lastOsc[i]) < 0.001f)
          continue;
        lastOsc[i] = m;
        curioOsc.sendFloat(oscAddress(bank->jacks[i].key), m);
      }
      return;
    }
    for (int i = 0; i < bank->count; i++) {
      if (!inputs[i].isConnected())
        continue;
      int v = (int) clamp(std::round(inputs[i].getVoltage() / 10.f * 127.f), 0.f, 127.f);
      if (v == lastValues[i])
        continue;
      lastValues[i] = v;
      midi::Message m;
      m.setStatus(0xb);
      m.setNote(bank->jacks[i].cc);
      m.setValue(v);
      midiOutput.sendMessage(m);
    }
  }

  json_t* dataToJson() override {
    json_t* rootJ = json_object();
    json_object_set_new(rootJ, "midi", midiOutput.toJson());
    json_object_set_new(rootJ, "osc", json_boolean(useOsc));
    return rootJ;
  }

  void dataFromJson(json_t* rootJ) override {
    json_t* midiJ = json_object_get(rootJ, "midi");
    if (midiJ)
      midiOutput.fromJson(midiJ);
    json_t* oscJ = json_object_get(rootJ, "osc");
    if (oscJ)
      useOsc = json_boolean_value(oscJ);
    // The channel belongs to the bank, whatever a saved patch says.
    midiOutput.setChannel(bank->channel - 1);
  }
};

// A name printed beside a jack, colored by level. SVG text does not render in Rack, so labels are drawn here.
struct CurioLabel : Widget {
  std::string text;
  NVGcolor color = nvgRGB(0x21, 0x1d, 0x1a);
  float fontSize = 9.f;

  void draw(const DrawArgs& args) override {
    std::shared_ptr<window::Font> font = APP->window->loadFont(asset::system("res/fonts/DejaVuSans.ttf"));
    if (!font || font->handle < 0)
      return;
    nvgFontFaceId(args.vg, font->handle);
    nvgFontSize(args.vg, fontSize);
    nvgFillColor(args.vg, color);
    nvgTextAlign(args.vg, NVG_ALIGN_LEFT | NVG_ALIGN_TOP);
    nvgTextLineHeight(args.vg, 1.05f);
    nvgTextBox(args.vg, 0, 0, box.size.x, text.c_str(), NULL);
  }
};

static CurioLabel* makeLabel(Vec pos, Vec size, std::string text, NVGcolor color, float fontSize) {
  CurioLabel* l = new CurioLabel;
  l->box.pos = pos;
  l->box.size = size;
  l->text = text;
  l->color = color;
  l->fontSize = fontSize;
  return l;
}

// Two columns of eight jacks, each with its name to the right.
static void addJacks(ModuleWidget* w, Module* module, const CurioBank* bank, int count, const char* const* names, const int* levels) {
  for (int i = 0; i < 16; i++) {
    int col = i / 8;
    int row = i % 8;
    float x = 6.f + col * 40.f;
    float y = 30.f + row * 12.f;
    w->addInput(createInputCentered<PJ301MPort>(mm2px(Vec(x, y)), module, i));
    w->addInput(createInputCentered<PJ301MPort>(mm2px(Vec(x + 8.5f, y)), module, 16 + i));
    if (i < count)
      w->addChild(makeLabel(mm2px(Vec(x + 13.f, y - 4.2f)), mm2px(Vec(23.f, 9.f)), names[i], LEVEL_COLORS[levels[i]], 8.f));
  }
}

struct CurioWidget : ModuleWidget {
  const CurioBank* bank;

  CurioWidget(CurioModule* module, const CurioBank* b) : bank(b) {
    setModule(module);
    setPanel(createPanel(asset::plugin(pluginInstance, "res/Curio.svg")));
    addChild(makeLabel(mm2px(Vec(4.f, 6.f)), mm2px(Vec(73.28f, 8.f)), bank->title, nvgRGB(0x21, 0x1d, 0x1a), 14.f));
    addChild(makeLabel(mm2px(Vec(4.f, 14.f)), mm2px(Vec(73.28f, 8.f)),
      string::f("MIDI ch %d, CC %d-%d. Left jack: 0 V From, 10 V To. Right jack: on/off gate (OSC).", bank->channel, bank->jacks[0].cc, bank->jacks[bank->count - 1].cc),
      nvgRGB(0x6d, 0x65, 0x5d), 8.f));
    const char* names[16];
    int levels[16];
    for (int i = 0; i < 16; i++) {
      names[i] = i < bank->count ? bank->jacks[i].label : "";
      levels[i] = i < bank->count ? bank->jacks[i].level : 0;
    }
    addJacks(this, module, bank, bank->count, names, levels);
  }

  void appendContextMenu(Menu* menu) override {
    CurioModule* module = dynamic_cast<CurioModule*>(this->module);
    if (!module)
      return;
    menu->addChild(new MenuSeparator);
    if (bank->jacks[0].key[0])
      menu->addChild(createBoolPtrMenuItem("Send by OSC to the desktop app (port 7000)", "", &module->useOsc));
    menu->addChild(createMenuLabel("MIDI output (to the Curiosities app in a browser)"));
    appendMidiMenu(menu, &module->midiOutput);
  }
};

